    const fin = g.score >= g.n;
    g.hint = 0; g.elim = -1; this.m.hand = null; g.step = 0; g.advanced = false;
    // combo: consecutive correct answers without a mistake in between
    g.combo = (g.rw === 0) ? (g.combo || 0) + 1 : 1; g.bestCombo = Math.max(g.bestCombo || 0, g.combo);
    const comboHit = g.combo >= 3;
    this.sfx(g.type === 'bowling' ? 'strike' : g.type === 'shoot' ? 'boom' : (LV.games[this.m.gi] || {}).skin === 'balloon' ? 'pop' : 'good', g.combo);
    if (comboHit) { this.sfx('combo'); this.buzz([30, 40, 30]); } else this.buzz(30);
